package raider.dsl.lineage.proj

/** Projection of a replayed lineage call-graph into a readable generated Scala
  * source string (LIN-02C, ADR-027). The renderer carries no data inline: node
  * payloads stay in the lineage-data resource and appear only as
  * `// data: <dataRef>` comments, so the generated file and the data resource
  * are separate artifacts joined by the comparator.
  */
enum NodeKind:
  case ModelCall(model: String, round: Int)
  case ToolCall(tool: String, recovery: String)
  case Delegation(agent: String)
  case Phase(name: String)

final case class NodeView(
    id: String,
    kind: NodeKind,
    parentId: Option[String],
    children: Vector[NodeView],
    dataRef: Option[String]
)

trait LineageView:
  def runId: String
  def roots: Vector[NodeView]

enum RenderError:
  case UnknownKind(detail: String)
  case Empty
  case Cyclic(id: String)

object LineageRenderer:

  private val Header =
    "// Generated by Raider lineage projection (ADR-027). Do not edit — comparator detects edits."

  private val Indent = "  "

  /** Renders the view deterministically: roots and children are walked in
    * order, so the output is byte-identical on repeat (LIN2-C-01). All mutable
    * state (output buffer, def-name counters, cycle path) is local to this
    * invocation — concurrent renders never interfere (LIN2-C-03).
    *
    * Typed failures: `Empty` for a rootless graph, `Cyclic` when a node id
    * repeats on the current root-to-node path, `UnknownKind` for a node kind
    * this revision does not render (defensive against future wire revisions).
    */
  def render(v: LineageView): Either[RenderError, String] =
    if v.roots.isEmpty then Left(RenderError.Empty)
    else
      val out = new StringBuilder
      val path = scala.collection.mutable.Set.empty[String]
      val defCounts = scala.collection.mutable.HashMap.empty[String, Int]
      out.append(Header).append('\n')
      out.append("object lineage_").append(slug(v.runId)).append(":\n")

      def addLine(indent: String, text: String): Unit =
        out.append(indent).append(text).append('\n')
        ()

      def dataSuffix(n: NodeView): String =
        // data refs enter a `//` comment too, so they pass through the same
        // escape discipline as quoted literals (W9 review F4).
        n.dataRef.fold("")(ref => " // data: " + escape(ref))

      def nextDefName(base: String): String =
        val seen = defCounts.getOrElse(base, 0)
        defCounts(base) = seen + 1
        if seen == 0 then base else base + "_" + (seen + 1)

      /** Indentation of the first NON-comment statement of a named def body, as
        * the Scala 3 parser binds it: comment lines never open an indentation
        * region, so when the direct children render as comments only, the body
        * region binds at the first nested named def (pre-order walk, the same
        * order the lines are emitted in). `None` means the body renders no def
        * at all — the region then binds to the closing line itself, which can
        * keep the children width. Only called after a successful acyclic walk,
        * so the recursion terminates.
        */
      def firstDefIndent(nodes: Vector[NodeView], at: String): Option[String] =
        if nodes.isEmpty then None
        else
          val n = nodes.head
          val named =
            n.kind.isInstanceOf[NodeKind.Delegation] || n.kind
              .isInstanceOf[NodeKind.Phase]
          if named then Some(at)
          else
            firstDefIndent(n.children, at + Indent).orElse(
              firstDefIndent(nodes.tail, at)
            )

      def namedDefHeader(indent: String, base: String, n: NodeView): Unit =
        val name = nextDefName(base)
        if n.children.isEmpty then
          addLine(indent, "def " + name + "(): Unit = ()" + dataSuffix(n))
        else addLine(indent, "def " + name + "(): Unit =" + dataSuffix(n))

      def walk(
          nodes: Vector[NodeView],
          indent: String
      ): Either[RenderError, Unit] =
        nodes.foldLeft[Either[RenderError, Unit]](Right(()))((acc, n) =>
          acc.flatMap(_ => visit(n, indent))
        )

      def visit(n: NodeView, indent: String): Either[RenderError, Unit] =
        if path.contains(n.id) then Left(RenderError.Cyclic(n.id))
        else
          path += n.id
          val kind: Matchable = n.kind
          val emitted: Either[RenderError, Unit] = kind match
            case NodeKind.ModelCall(model, round) =>
              Right(
                addLine(
                  indent,
                  "// model(\"" + escape(
                    model
                  ) + "\", round = " + round + ")" + dataSuffix(n)
                )
              )
            case NodeKind.ToolCall(tool, recovery) =>
              Right(
                addLine(
                  indent,
                  "// tool(\"" + escape(tool) + "\", recovery = \"" + escape(
                    recovery
                  ) + "\")" +
                    dataSuffix(n)
                )
              )
            case NodeKind.Delegation(agent) =>
              Right(namedDefHeader(indent, "delegation_" + slug(agent), n))
            case NodeKind.Phase(name) =>
              Right(namedDefHeader(indent, "phase_" + slug(name), n))
            case other =>
              val describe =
                Option(other).fold("null")(_.getClass.getSimpleName)
              Left(
                RenderError.UnknownKind("unsupported node kind: " + describe)
              )
          emitted
            .flatMap(_ => walk(n.children, indent + Indent))
            .map { _ =>
              // named defs with a non-empty body need the closing expression.
              // The body region of `def ...: Unit =` opens at the first
              // NON-comment statement (comments never bind an indentation
              // width — W10 review finding, L30/L34), so the closing `()`
              // must start at a width the parser has ALREADY bound: the
              // first nested def's width when all direct children render as
              // comments, else the children width (bound either at the first
              // def child or at the closer line itself). A closer at the
              // shallow children width under comment-only ancestors falls
              // BETWEEN open regions and dotc rejects the projection.
              val isNamedDef =
                kind.isInstanceOf[NodeKind.Delegation] || kind
                  .isInstanceOf[NodeKind.Phase]
              if isNamedDef && n.children.nonEmpty then
                addLine(
                  firstDefIndent(n.children, indent + Indent)
                    .getOrElse(indent + Indent),
                  "()"
                )
              path -= n.id
            }

      walk(v.roots, Indent).map(_ => out.toString)

  /** Identifier slug: letters/digits/underscore kept, everything else mapped to
    * `_`; an empty or digit-leading result is prefixed so it is a valid Scala
    * identifier. Deterministic.
    */
  private def slug(raw: String): String =
    val cleaned = raw.map(c => if c.isLetterOrDigit || c == '_' then c else '_')
    if cleaned.isEmpty || cleaned.head.isDigit then "_" + cleaned else cleaned

  /** Escape discipline for free text entering the generated source (W9 review
    * F4): besides the Scala-literal escapes `\` and `"`, control characters are
    * neutralized exactly like the canonical-form esc of the runtime GraphHash —
    * `\n`, `\r`, `\t` become the two-character sequences `\n`/`\r`/`\t`, and
    * every other C0 control (U+0000–U+001F) or DEL (U+007F) becomes `\xHH` (two
    * lowercase hex digits of the code point). A model/tool/recovery name or
    * data ref carrying raw newlines can therefore no longer split a `//`
    * comment: every emitted comment line stays single-line, so the generated
    * artifact keeps its line structure regardless of hostile node payloads.
    * Deterministic and injective by construction: each `\` in the output opens
    * exactly one of the listed sequences, and no escaped text contains a raw
    * newline, quote or control character.
    */
  private def escape(raw: String): String =
    val out = new StringBuilder(raw.length + 8)
    raw.foreach {
      case '\\'                          => out.append("\\\\")
      case '"'                           => out.append("\\\"")
      case '\n'                          => out.append("\\n")
      case '\r'                          => out.append("\\r")
      case '\t'                          => out.append("\\t")
      case c if c < ' ' || c == '\u007f' => out.append(f"\\x${c.toInt}%02x")
      case c                             => out.append(c)
    }
    out.result()
